package net.civeira.phylax.feature.observe.observedsource.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class RateLimitVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property rate limit of observed source ")
  void test_rate_limit_v_o_builder() {
    Assertions.assertFalse(RateLimitVO.nullValue().getRateLimit().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(RateLimitVO.tryFrom(null).getRateLimit().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals(1, RateLimitVO.from(1).getRateLimit().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> RateLimitVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", RateLimitVO.from(1).toString());
  }
}
